insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000001','Spice Alley','Chippendale','Food & drink',array['Date night','Birthday dinner','Hidden gems']::text[],'Lanterns overhead, little kitchens all around. A casual laneway for choosing dinner together, one stall at a time.','Kensington Street, Chippendale NSW 2008',-33.8855,151.2015,'https://spice-alley.com.au/','Sydney','{"src":"photos/spice-alley.webp","smallSrc":"photos/spice-alley-480.webp","width":960,"height":1438,"alt":"Red lanterns above the narrow dining laneway at Spice Alley, Chippendale.","title":"Going home gnangarra-51.jpg","author":"Gnangarra","source":"https://commons.wikimedia.org/wiki/File:Going_home_gnangarra-51.jpg","license":"CC BY 2.5 au","licenseUrl":"https://creativecommons.org/licenses/by/2.5/au/deed.en","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000002','Opera Bar','Circular Quay','Bars',array['After-work drinks','Date night','Birthday dinner']::text[],'A drink beside the harbour, with the Opera House on one side and the bridge on the other. Plan ahead for busy evenings.','Lower Concourse, Sydney Opera House, Sydney NSW 2000',-33.8572,151.2142,'https://operabar.com.au/','Sydney','{"src":"photos/opera-bar.webp","smallSrc":"photos/opera-bar-480.webp","alt":"Tables and visitors at Opera Bar beside Sydney Harbour.","author":"Alex Proimos from Sydney, Australia","source":"https://commons.wikimedia.org/wiki/File%3AOpera%20Bar%20(3401033971).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000003','Royal Botanic Garden','Sydney','Outdoors',array['Weekend wandering','Family outings','Date night']::text[],'Take the long way through palms, garden paths and harbour lawns. Leave room in the afternoon for an unhurried picnic.','Mrs Macquaries Road, Sydney NSW 2000',-33.8642,151.2166,'https://www.botanicgardens.org.au/royal-botanic-garden-sydney','Sydney','{"src":"photos/botanic-garden.webp","smallSrc":"photos/botanic-garden-480.webp","width":960,"height":640,"alt":"Succulents and mature trees in the Royal Botanic Garden, Sydney.","title":"Sydney (AU), Royal Botanic Gardens -- 2019 -- 3079.jpg","author":"Dietmar Rabich","source":"https://commons.wikimedia.org/wiki/File:Sydney_(AU),_Royal_Botanic_Gardens_--_2019_--_3079.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000004','White Rabbit Gallery & Tea House','Chippendale','Cafes',array['Coffee dates','Hidden gems','Weekend wandering']::text[],'Contemporary Chinese art, then tea and a quiet conversation downstairs. The photograph shows the gallery exterior; check exhibition changeover dates.','30 Balfour Street, Chippendale NSW 2008',-33.8875,151.2006,'https://whiterabbitcollection.org/','Sydney','{"src":"photos/white-rabbit.webp","smallSrc":"photos/white-rabbit-480.webp","width":960,"height":720,"alt":"The brick exterior of White Rabbit Gallery in Chippendale.","title":"White Rabbit gallery December 2025.jpg","author":"Nick-D","source":"https://commons.wikimedia.org/wiki/File:White_Rabbit_gallery_December_2025.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000005','Circular Quay promenade','Circular Quay','Attractions',array['Weekend wandering','Family outings','Date night']::text[],'Ferries coming and going, a little sea air, and the city opening out around the water. A lovely meeting point before the rest of the day.','Circular Quay, Sydney NSW 2000',-33.8609,151.2121,'https://www.sydney.com/destinations/sydney/sydney-city/circular-quay','Sydney','{"src":"photos/quay-promenade.webp","smallSrc":"photos/quay-promenade-480.webp","width":960,"height":720,"alt":"People walking along Circular Quay promenade beside Sydney Cove.","title":"AUS Sydney, Central Business District, Circular Quay 012.jpg","author":"-wuppertaler","source":"https://commons.wikimedia.org/wiki/File:AUS_Sydney,_Central_Business_District,_Circular_Quay_012.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000006','Observatory Hill Park','The Rocks','Outdoors',array['Hidden gems','Date night','Weekend wandering']::text[],'A grassy hill, old trees and one of the city’s best bridge views. Bring a picnic rug and allow for uphill paths.','Upper Fort Street, Millers Point NSW 2000',-33.8596,151.2048,'https://www.cityofsydney.nsw.gov.au/parks/observatory-hill-park','Sydney','{"src":"photos/observatory-hill.webp","smallSrc":"photos/observatory-hill-480.webp","width":960,"height":540,"alt":"Sydney Harbour Bridge and the harbour seen from Observatory Hill.","title":"View from Observatory Hill, Sydney (483413) (9443070588).jpg","author":"Robert Linsdell from St. Andrews, Canada","source":"https://commons.wikimedia.org/wiki/File:View_from_Observatory_Hill,_Sydney_(483413)_(9443070588).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000007','Darling Square','Haymarket','Food & drink',array['Birthday dinner','Family outings','After-work drinks']::text[],'A whole neighbourhood of dining possibilities around The Exchange. Browse together, then choose a table that suits the group.','Steam Mill Lane, Haymarket NSW 2000',-33.8771,151.202,'https://www.darlingsq.com/','Sydney','{"src":"photos/darling-square.webp","smallSrc":"photos/darling-square-480.webp","width":960,"height":720,"alt":"The illuminated Exchange building and dining precinct at Darling Square.","title":"Darling Square Sydney.jpg","author":"MDRX","source":"https://commons.wikimedia.org/wiki/File:Darling_Square_Sydney.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000008','Art Gallery of New South Wales','Sydney','Art & culture',array['Weekend wandering','Family outings','Date night']::text[],'Let a favourite painting decide the pace. Explore the collection, the architecture and the paths towards the harbour.','Art Gallery Road, Sydney NSW 2000',-33.8688,151.2173,'https://www.artgallery.nsw.gov.au/','Sydney','{"src":"photos/art-gallery.webp","smallSrc":"photos/art-gallery-480.webp","width":960,"height":540,"alt":"The columned entrance to the Art Gallery of New South Wales.","title":"Sydney (AU), Art Gallery of New South Wales -- 2019 -- 3103.jpg","author":"Dietmar Rabich","source":"https://commons.wikimedia.org/wiki/File:Sydney_(AU),_Art_Gallery_of_New_South_Wales_--_2019_--_3103.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000009','Barangaroo Reserve','Barangaroo','Outdoors',array['Weekend wandering','Family outings','Hidden gems']::text[],'Sandstone edges, native planting and a waterfront walk made for slowing down. Bring water and sun protection.','Hickson Road, Barangaroo NSW 2000',-33.8587,151.2019,'https://www.barangaroo.com/see-and-do/barangaroo-reserve','Sydney','{"src":"photos/barangaroo-reserve.webp","smallSrc":"photos/barangaroo-reserve-480.webp","width":960,"height":720,"alt":"Grassy lawns, waterfront paths and trees at Barangaroo Reserve.","title":"AUS Sydney, Central Business District, Barangaroo Reserve 022.jpg","author":"-wuppertaler","source":"https://commons.wikimedia.org/wiki/File:AUS_Sydney,_Central_Business_District,_Barangaroo_Reserve_022.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000010','Chinese Garden of Friendship','Darling Harbour','Attractions',array['Date night','Hidden gems','Family outings']::text[],'Step away from the city into pavilions, winding paths and koi ponds. A small, thoughtful escape; admission charges apply.','Pier Street, Darling Harbour NSW 2000',-33.8764,151.2024,'https://www.darlingharbour.com/see-and-do/chinese-garden-of-friendship','Sydney','{"src":"photos/chinese-garden.webp","smallSrc":"photos/chinese-garden-480.webp","width":960,"height":720,"alt":"A pavilion, pond and rocks in the Chinese Garden of Friendship.","title":"2022-10-15 Chinese Garden of Friendship, Sydney 3.jpg","author":"Maksym Kozlenko","source":"https://commons.wikimedia.org/wiki/File:2022-10-15_Chinese_Garden_of_Friendship,_Sydney_3.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000011','Queen Victoria Building','Sydney','Shopping',array['Weekend wandering','Coffee dates','Places to try']::text[],'Look up at the clocks and stained glass before exploring the arcades. Make an afternoon of browsing and a tea stop.','455 George Street, Sydney NSW 2000',-33.8718,151.2067,'https://www.qvb.com.au/','Sydney','{"src":"photos/qvb.webp","smallSrc":"photos/qvb-480.webp","alt":"The ornate interior and Royal Clock of the Queen Victoria Building in Sydney.","author":"Kgbo","source":"https://commons.wikimedia.org/wiki/File%3AInterior%20of%20Queen%20Victoria%20Building%20with%20Royal%20Clock%2C%20Sydney%2002.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000012','Museum of Contemporary Art Australia','The Rocks','Art & culture',array['Date night','Weekend wandering','Coffee dates']::text[],'Harbourside contemporary art with plenty to talk about afterwards. Check current exhibition access and ticket conditions.','140 George Street, The Rocks NSW 2000',-33.8599,151.209,'https://www.mca.com.au/','Sydney','{"src":"photos/mca.webp","smallSrc":"photos/mca-480.webp","width":960,"height":540,"alt":"The sandstone facade of the Museum of Contemporary Art Australia.","title":"The Museum of Contemporary Art, Sydney (former MSB Building).jpg","author":"Briandhana Krishnatirta Kusaditya","source":"https://commons.wikimedia.org/wiki/File:The_Museum_of_Contemporary_Art,_Sydney_(former_MSB_Building).jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000013','Paddy’s Markets Haymarket','Haymarket','Shopping',array['Family outings','Weekend wandering','Hidden gems']::text[],'Browse the covered stalls for a small find or something unexpected. Trading days vary, so check before setting out.','9–13 Hay Street, Haymarket NSW 2000',-33.8792,151.2035,'https://paddysmarkets.com.au/','Sydney','{"src":"photos/paddys-markets.webp","smallSrc":"photos/paddys-markets-480.webp","width":960,"height":720,"alt":"The Market City entrance above Paddy''s Markets in Haymarket.","title":"Haymarket Market City entrance.JPG","author":"J Bar","source":"https://commons.wikimedia.org/wiki/File:Haymarket_Market_City_entrance.JPG","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000014','Hyde Park','Sydney','Outdoors',array['Weekend wandering','Family outings','Coffee dates']::text[],'A shady pause beneath the fig trees, right in the middle of town. Pair a slow walk with something from a nearby cafe.','Elizabeth Street, Sydney NSW 2000',-33.8731,151.2113,'https://www.cityofsydney.nsw.gov.au/parks/hyde-park','Sydney','{"src":"photos/hyde-park.webp","smallSrc":"photos/hyde-park-480.webp","width":960,"height":720,"alt":"A shaded, tree-lined path through Hyde Park in central Sydney.","title":"AUS Sydney, Central Business District, Hyde Park 020.jpg","author":"-wuppertaler","source":"https://commons.wikimedia.org/wiki/File:AUS_Sydney,_Central_Business_District,_Hyde_Park_020.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000015','State Library of New South Wales','Sydney','Art & culture',array['Hidden gems','Weekend wandering']::text[],'Reading rooms, sandstone and changing displays. An easy way to turn an ordinary lunch break into a little discovery.','1 Shakespeare Place, Sydney NSW 2000',-33.8662,151.2128,'https://www.sl.nsw.gov.au/','Sydney','{"src":"photos/state-library.webp","smallSrc":"photos/state-library-480.webp","width":960,"height":507,"alt":"The sandstone Mitchell and Dixson wings of the State Library of New South Wales.","title":"Mitchell and Dixson wings, State Library of New South Wales, 2023.jpg","author":"Geoff Barker","source":"https://commons.wikimedia.org/wiki/File:Mitchell_and_Dixson_wings,_State_Library_of_New_South_Wales,_2023.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000016','Pyrmont Bridge','Darling Harbour','Attractions',array['Weekend wandering','Family outings','Date night']::text[],'Walk across the harbour on a historic swing bridge. Come back after dark to see the waterfront in a different light.','Pyrmont Bridge, Darling Harbour NSW 2000',-33.8705,151.2013,'https://www.darlingharbour.com/see-and-do/pyrmont-bridge','Sydney','{"src":"photos/pyrmont-bridge.webp","smallSrc":"photos/pyrmont-bridge-480.webp","width":960,"height":720,"alt":"The pedestrian Pyrmont Bridge crossing Darling Harbour.","title":"Pyrmont Bridge February 2014.jpg","author":"Nick-D","source":"https://commons.wikimedia.org/wiki/File:Pyrmont_Bridge_February_2014.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000017','The Glenmore Hotel','The Rocks','Bars',array['After-work drinks','Date night','Birthday dinner']::text[],'Head upstairs for a rooftop drink with Sydney Harbour in view, or settle in for pub food downstairs. Check bookings and rooftop availability before bringing a group.','96 Cumberland Street, The Rocks NSW 2000',-33.8587,151.2074,'https://www.theglenmore.com.au/','Sydney','{"src":"photos/glenmore.webp","smallSrc":"photos/glenmore-480.webp","width":960,"height":720,"alt":"The Glenmore Hotel exterior on Cumberland Street in The Rocks.","title":"Glenmore Hotel - The Rocks NSW (12866054844).jpg","author":"sv1ambo","source":"https://commons.wikimedia.org/wiki/File:Glenmore_Hotel_-_The_Rocks_NSW_(12866054844).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000018','The Australian Heritage Hotel','The Rocks','Bars',array['After-work drinks','Birthday dinner','Places to try']::text[],'A corner pub for Australian craft beer, pizza and a catch-up after wandering The Rocks. The exterior photograph shows the hotel, not a current menu.','100 Cumberland Street, The Rocks NSW 2000',-33.8594,151.207,'https://www.australianheritagehotel.com/','Sydney','{"src":"photos/australian-heritage.webp","smallSrc":"photos/australian-heritage-480.webp","width":960,"height":1352,"alt":"The Australian Heritage Hotel at the corner of Cumberland and Gloucester Streets.","title":"Sydney The Rocks Australian Hotel seen from the north.jpg","author":"Ymblanter","source":"https://commons.wikimedia.org/wiki/File:Sydney_The_Rocks_Australian_Hotel_seen_from_the_north.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000019','The Lord Nelson Brewery Hotel','Millers Point','Bars',array['After-work drinks','Hidden gems','Date night']::text[],'Sandstone walls, a heritage pub and a reason to take the quieter streets home. Browse the current beer and dining menus before choosing your table.','19 Kent Street, Millers Point NSW 2000',-33.8582,151.2034,'https://lordnelsonbrewery.com/','Sydney','{"src":"photos/lord-nelson.webp","smallSrc":"photos/lord-nelson-480.webp","width":960,"height":720,"alt":"The sandstone exterior of the Lord Nelson Brewery Hotel in Millers Point.","title":"Lord Nelson Hotel & Brewery - Miller''s Point, Sydney, NSW (7889955274).jpg","author":"sv1ambo","source":"https://commons.wikimedia.org/wiki/File:Lord_Nelson_Hotel_%26_Brewery_-_Miller%27s_Point,_Sydney,_NSW_(7889955274).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000020','Hero of Waterloo','Millers Point','Bars',array['After-work drinks','Hidden gems','Date night']::text[],'An old sandstone pub with a lively musical side. Check the live-music programme and dining hours before making an evening of it.','81 Lower Fort Street, Millers Point NSW 2000',-33.8578,151.2058,'https://heroofwaterloo.com.au/','Sydney','{"src":"photos/hero-waterloo.webp","smallSrc":"photos/hero-waterloo-480.webp","width":960,"height":720,"alt":"The historic Hero of Waterloo Hotel on Lower Fort Street.","title":"Hero of Waterloo Hotel - Miller''s Point, Sydney, NSW (7875802778).jpg","author":"sv1ambo","source":"https://commons.wikimedia.org/wiki/File:Hero_of_Waterloo_Hotel_-_Miller%27s_Point,_Sydney,_NSW_(7875802778).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000021','The Orient Hotel','The Rocks','Bars',array['After-work drinks','Birthday dinner','Places to try']::text[],'Choose a courtyard catch-up, a pub lunch or the upstairs dining terrace overlooking the laneways. Check the venue''s current spaces and bookings for your group.','89 George Street, The Rocks NSW 2000',-33.8591,151.2086,'https://www.orienthotel.com.au/','Sydney','{"src":"photos/orient-hotel.webp","smallSrc":"photos/orient-hotel-480.webp","width":960,"height":720,"alt":"The Orient Hotel exterior on George Street in The Rocks.","title":"Orient Hotel - The Rocks, Sydney, NSW (7875752108).jpg","author":"sv1ambo","source":"https://commons.wikimedia.org/wiki/File:Orient_Hotel_-_The_Rocks,_Sydney,_NSW_(7875752108).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000022','Coogee Bay Hotel','Coogee','Bars',array['After-work drinks','Birthday dinner','Date night']::text[],'A beachside pub stop with several spaces for food and drinks. Pick the bar or dining area that suits your afternoon; the photo shows the hotel''s front bar.','253 Coogee Bay Road, Coogee NSW 2034',-33.9209,151.2565,'https://coogeebayhotel.com.au/','Sydney','{"src":"photos/coogee-bay-hotel.webp","smallSrc":"photos/coogee-bay-hotel-480.webp","width":960,"height":540,"alt":"Inside the front bar area at Coogee Bay Hotel.","title":"Marra bar at Coogee Bay Hotel.jpg","author":"Sam Wilson (taken with Samsung Galaxy S21 FE 5G)","source":"https://commons.wikimedia.org/wiki/File:Marra_bar_at_Coogee_Bay_Hotel.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000023','Bathers'' Pavilion','Mosman','Food & drink',array['Date night','Birthday dinner','Coffee dates']::text[],'A beachside dining destination at Balmoral with several distinct restaurants and a kiosk. Choose your dining space and check its own menu and booking arrangements.','4 The Esplanade, Balmoral NSW 2088',-33.8227,151.251,'https://www.batherspavilion.com.au/','Sydney','{"src":"photos/bathers-pavilion.webp","smallSrc":"photos/bathers-pavilion-480.webp","width":960,"height":643,"alt":"Bathers'' Pavilion beside Balmoral Beach.","title":"The Bathers'' Pavillion.jpg","author":"{{{1}}}","source":"https://commons.wikimedia.org/wiki/File:The_Bathers%27_Pavillion.jpg","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000024','Harry''s Cafe de Wheels — Woolloomooloo','Woolloomooloo','Food & drink',array['Places to try','Family outings','Weekend wandering']::text[],'A small pie-and-hot-dog stop beside Woolloomooloo''s waterfront. Keep it casual, then wander along the wharf; check the kiosk''s current opening hours.','Corner of Cowper Wharf Roadway and Brougham Street, Woolloomooloo NSW 2011',-33.869259,151.221193,'https://www.harryscafedewheels.com.au/','Sydney','{"src":"photos/harrys-woolloomooloo.webp","smallSrc":"photos/harrys-woolloomooloo-480.webp","width":960,"height":705,"alt":"Harry''s Cafe de Wheels pie kiosk in Woolloomooloo.","title":"Harrys Cafe de Wheels (6960417355).jpg","author":"Eva Rinaldi","source":"https://commons.wikimedia.org/wiki/File:Harrys_Cafe_de_Wheels_(6960417355).jpg","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000025','Doyles on the Beach','Watsons Bay','Food & drink',array['Date night','Birthday dinner','Family outings']::text[],'Seafood at the water''s edge, with a ferry outing on either side of lunch. This is the sit-down beach restaurant, not Doyles'' separate wharf takeaway.','11 Marine Parade, Watsons Bay NSW 2030',-33.8429,151.2819,'https://www.doyles.com.au/','Sydney','{"src":"photos/doyles.webp","smallSrc":"photos/doyles-480.webp","width":960,"height":619,"alt":"Doyles on the Beach restaurant beside the sand at Watsons Bay.","title":"(1)Doyles Beach Restaurant Watsons Bay.jpg","author":"Sardaka","source":"https://commons.wikimedia.org/wiki/File:(1)Doyles_Beach_Restaurant_Watsons_Bay.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000026','Watsons Bay Boutique Hotel','Watsons Bay','Food & drink',array['Birthday dinner','Date night','Weekend wandering']::text[],'A harbourside beach-club meal or a relaxed catch-up after the ferry ride. Check dining bookings and events; the photograph shows the hotel exterior.','10 Marine Parade, Watsons Bay NSW 2030',-33.843,151.2823,'https://watsonsbayhotel.com.au/','Sydney','{"src":"photos/watsons-bay-hotel.webp","smallSrc":"photos/watsons-bay-hotel-480.webp","width":960,"height":576,"alt":"The exterior of Watsons Bay Boutique Hotel, historically known as the Palace Hotel.","title":"(1)Palace Hotel Watsons Bay.jpg","author":"Sardaka","source":"https://commons.wikimedia.org/wiki/File:(1)Palace_Hotel_Watsons_Bay.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000027','Luna Park Sydney','Milsons Point','Activities',array['Family outings','Date night','Weekend wandering']::text[],'Walk through the smiling face for a harbourside amusement-park day. Check the current ride passes, operating calendar and height restrictions before visiting.','1 Olympic Drive, Milsons Point NSW 2061',-33.8476,151.21,'https://www.lunaparksydney.com/','Sydney','{"src":"photos/luna-park.webp","smallSrc":"photos/luna-park-480.webp","width":960,"height":720,"alt":"The smiling face entrance to Luna Park Sydney at Milsons Point.","title":"Syd2007 Luna Park entrance 1.jpg","author":"Orderinchaos","source":"https://commons.wikimedia.org/wiki/File:Syd2007_Luna_Park_entrance_1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000028','Taronga Zoo Sydney','Mosman','Activities',array['Family outings','Weekend wandering','Places to try']::text[],'Make a day of wildlife habitats and harbour views on the north shore. Book admission, check transport options and allow time for the zoo''s sloping paths.','Bradleys Head Road, Mosman NSW 2088',-33.843333,151.241111,'https://taronga.org.au/sydney-zoo','Sydney','{"src":"photos/taronga-zoo.webp","smallSrc":"photos/taronga-zoo-480.webp","width":960,"height":540,"alt":"Giraffes in their enclosure at Taronga Zoo, with Sydney in the distance.","title":"Taronga Zoo, Sydney (483465) (24793297802).jpg","author":"Robert Linsdell from St. Andrews, Canada","source":"https://commons.wikimedia.org/wiki/File:Taronga_Zoo,_Sydney_(483465)_(24793297802).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000029','SEA LIFE Sydney Aquarium','Darling Harbour','Activities',array['Family outings','Date night','Places to try']::text[],'An indoor underwater detour through marine habitats at Darling Harbour. Check timed admission and current visitor information; the photograph shows the waterfront building.','1–5 Wheat Road, Sydney NSW 2000',-33.8694,151.2019,'https://www.visitsealife.com/sydney/','Sydney','{"src":"photos/sea-life.webp","smallSrc":"photos/sea-life-480.webp","width":960,"height":540,"alt":"The SEA LIFE Sydney Aquarium building beside Darling Harbour.","title":"Sydney Aquarium Sea Life.jpg","author":"Moatazayman","source":"https://commons.wikimedia.org/wiki/File:Sydney_Aquarium_Sea_Life.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000030','Sydney Opera House','Circular Quay','Art & culture',array['Date night','Family outings','Places to try']::text[],'Go beyond the postcard with a performance or a guided tour inside the sails. Book the experience you want; walking the forecourt is a separate, unticketed visit.','Bennelong Point, Sydney NSW 2000',-33.85681,151.21514,'https://www.sydneyoperahouse.com/visit','Sydney','{"src":"photos/opera-house.webp","smallSrc":"photos/opera-house-480.webp","width":960,"height":643,"alt":"The Sydney Opera House sails and forecourt beside the harbour.","title":"Sydney Opera House forecourt and concourse.jpg","author":"Peter Hall","source":"https://commons.wikimedia.org/wiki/File:Sydney_Opera_House_forecourt_and_concourse.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000031','Australian Museum','Sydney','Art & culture',array['Family outings','Weekend wandering','Places to try']::text[],'Natural history, dinosaurs and cultural collections opposite Hyde Park. General admission and special exhibitions have different arrangements; check the current programme.','1 William Street, Sydney NSW 2010',-33.8743,151.2134,'https://australian.museum/visit/','Sydney','{"src":"photos/australian-museum.webp","smallSrc":"photos/australian-museum-480.webp","width":960,"height":640,"alt":"An aerial view of the Australian Museum opposite Hyde Park, photographed from Sydney Tower.","title":"Sydney (AU), View from Sydney Tower, Australian Museum -- 2019 -- 3123.jpg","author":"Dietmar Rabich","source":"https://commons.wikimedia.org/wiki/File:Sydney_(AU),_View_from_Sydney_Tower,_Australian_Museum_--_2019_--_3123.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000032','Sydney Observatory','Millers Point','Art & culture',array['Date night','Hidden gems','Family outings']::text[],'Explore astronomy and the history of this hilltop observatory through its current visitor programme. Conservation works can affect access, so check before planning a tour.','1003 Upper Fort Street, Millers Point NSW 2000',-33.8596,151.2047,'https://powerhouse.com.au/visit/sydney-observatory','Sydney','{"src":"photos/sydney-observatory.webp","smallSrc":"photos/sydney-observatory-480.webp","width":960,"height":720,"alt":"The Sydney Observatory exterior illuminated at night.","title":"Sydney Observatory at night.JPG","author":"Hohohob","source":"https://commons.wikimedia.org/wiki/File:Sydney_Observatory_at_night.JPG","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000033','Bondi Icebergs Pool','Bondi Beach','Activities',array['Weekend wandering','Places to try','Date night']::text[],'An ocean-pool visit beside Bondi Beach, with the coastline stretching beyond the lanes. Pool fees, weather conditions and access rules apply; check before arriving.','1 Notts Avenue, Bondi Beach NSW 2026',-33.895134,151.27434,'https://icebergs.com.au/','Sydney','{"src":"photos/bondi-icebergs.webp","smallSrc":"photos/bondi-icebergs-480.webp","width":960,"height":1280,"alt":"The ocean pool at Bondi Icebergs beside Bondi Beach.","title":"Bondi Icebergs POOL, Bondi Beach, Australia (Unsplash).jpg","author":"Mike Wilson mkwlsn","source":"https://commons.wikimedia.org/wiki/File:Bondi_Icebergs_POOL,_Bondi_Beach,_Australia_(Unsplash).jpg","license":"CC0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/deed.en","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000034','Wendy Whiteley''s Secret Garden','Lavender Bay','Outdoors',array['Hidden gems','Date night','Weekend wandering']::text[],'Find a leafy path and a quiet bench in this much-loved Lavender Bay garden. Expect steps and uneven paths, and treat the planting and neighbours gently.','Lavender Street, Lavender Bay NSW 2060',-33.84375,151.20816,'https://www.wendyssecretgarden.org.au/','Sydney','{"src":"photos/wendys-garden.webp","smallSrc":"photos/wendys-garden-480.webp","width":960,"height":642,"alt":"Leafy paths and planting in Wendy Whiteley''s Secret Garden at Lavender Bay.","title":"(1)Wendy Whiteleys Garden 220.jpg","author":"Sardaka","source":"https://commons.wikimedia.org/wiki/File:(1)Wendy_Whiteleys_Garden_220.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000035','Cockatoo Island / Wareamah','Sydney Harbour','Attractions',array['Weekend wandering','Family outings','Places to try']::text[],'Take a ferry to former shipyards, convict-era buildings and wide harbour views. Check ferry services, current tours and site access before setting out.','Cockatoo Island, Sydney Harbour NSW 2039',-33.8475,151.1725,'https://www.cockatooisland.gov.au/en/','Sydney','{"src":"photos/cockatoo-island.webp","smallSrc":"photos/cockatoo-island-480.webp","width":960,"height":640,"alt":"A heritage industrial building on Cockatoo Island in Sydney Harbour.","title":"Cockatoo Island building.jpg","author":"Carmazina","source":"https://commons.wikimedia.org/wiki/File:Cockatoo_Island_building.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000036','Paddington Markets','Paddington','Shopping',array['Weekend wandering','Hidden gems','Family outings']::text[],'Browse local makers, clothing, crafts and food in the church grounds on market day. Check the Saturday programme rather than treating it as an everyday shopping centre.','395 Oxford Street, Paddington NSW 2021',-33.88724,151.22994,'https://www.paddingtonmarkets.com.au/','Sydney','{"src":"photos/paddington-markets.webp","smallSrc":"photos/paddington-markets-480.webp","width":960,"height":720,"alt":"Shoppers and outdoor stalls at Paddington Markets in April 2026.","title":"Part of Paddington Markets April 2026.jpg","author":"Nick-D","source":"https://commons.wikimedia.org/wiki/File:Part_of_Paddington_Markets_April_2026.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000037','Australian National Maritime Museum','Darling Harbour','Art & culture',array['Family outings','Weekend wandering','Places to try']::text[],'Explore ocean stories, waterfront galleries and historic vessels. Gallery admission and ship access can differ, so check tickets and boarding times for your visit.','2 Murray Street, Darling Harbour NSW 2000',-33.869167,151.198611,'https://www.sea.museum/en/visit','Sydney','{"src":"photos/maritime-museum.webp","smallSrc":"photos/maritime-museum-480.webp","width":960,"height":506,"alt":"The Australian National Maritime Museum seen from Pyrmont Bay ferry wharf.","title":"Australian National Maritime Museum from Pyrmont Bay ferry wharf.jpg","author":"Philip Terry Graham","source":"https://commons.wikimedia.org/wiki/File:Australian_National_Maritime_Museum_from_Pyrmont_Bay_ferry_wharf.jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000038','Shelly Beach','Manly','Outdoors',array['Weekend wandering','Family outings','Date night']::text[],'Follow the waterfront from Manly towards the sheltered sand at Cabbage Tree Bay. Bring a picnic and check local conditions; do not assume the beach is lifeguard-patrolled.','Shelly Beach, Marine Parade, Manly NSW 2095',-33.80055,151.29792,'https://www.northernbeaches.nsw.gov.au/things-to-do/recreation-area/shelly-beach','Sydney','{"src":"photos/shelly-beach.webp","smallSrc":"photos/shelly-beach-480.webp","width":960,"height":456,"alt":"Shelly Beach at Manly, beside Cabbage Tree Bay.","title":"Shelly Beach in Manly Sydney Australia.jpg","author":"Hardlinerr","source":"https://commons.wikimedia.org/wiki/File:Shelly_Beach_in_Manly_Sydney_Australia.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000039','Centennial Park','Centennial Park','Outdoors',array['Weekend wandering','Family outings','Coffee dates']::text[],'Ponds, broad lawns and room for a longer picnic or a slow walk. Choose an entrance that suits your route and check park notices before heading over.','Grand Drive, Centennial Park NSW 2021',-33.9,151.23333,'https://www.centennialparklands.com.au/','Sydney','{"src":"photos/centennial-park.webp","smallSrc":"photos/centennial-park-480.webp","width":960,"height":718,"alt":"Busbys Pond and its leafy banks in Centennial Park, Sydney.","title":"Busbys Pond 001a.jpg","author":"Sardaka","source":"https://commons.wikimedia.org/wiki/File:Busbys_Pond_001a.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000040','Camp Cove','Watsons Bay','Outdoors',array['Weekend wandering','Family outings','Date night']::text[],'A small harbour beach for a scenic pause on a Watsons Bay outing. Check beach conditions and national-park notices, and leave room for the walk back to the ferry.','Cliff Street, Watsons Bay NSW 2030',-33.83878,151.27919,'https://www.nationalparks.nsw.gov.au/visit-a-park/parks/sydney-harbour-national-park','Sydney','{"src":"photos/camp-cove.webp","smallSrc":"photos/camp-cove-480.webp","width":960,"height":298,"alt":"The sandy shore and harbour water at Camp Cove, Watsons Bay.","title":"Watsons Bay - Camp Cove Beach, Sydney 2 - Nov 2008.jpg","author":"Diliff","source":"https://commons.wikimedia.org/wiki/File:Watsons_Bay_-_Camp_Cove_Beach,_Sydney_2_-_Nov_2008.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000041','Osteria Luna','Sydney CBD','Food & drink',array['Date night','Birthday dinner','After-work drinks']::text[],'An underground Italian restaurant beneath The Charles Brasserie & Bar, with pasta, cocktails and a musical side. Check the current lunch, dinner and late-night programme before booking.','Basement, 68 King Street, Sydney NSW 2000',-33.8684667,151.2064392,'https://osterialuna.sydney/','Sydney','{"src":"","smallSrc":"","alt":"Osteria Luna: venue photo not yet available","author":"","source":"","license":"","licenseUrl":""}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000042','Dean & Nancy on 22','Sydney CBD','Bars',array['Date night','After-work drinks','Birthday dinner']::text[],'Cocktails and dining above the CBD on level 22 of A by Adina Sydney. Plan a sunset catch-up or an evening out, and check current bookings and entry conditions with the venue.','Level 22, A by Adina Sydney, 2 Hunter Street, Sydney NSW 2000',-33.8653794,151.2074682,'https://www.deanandnancyon22.com.au/','Sydney','{"src":"","smallSrc":"","alt":"Dean & Nancy on 22: venue photo not yet available","author":"","source":"","license":"","licenseUrl":""}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000043','The Bank Hotel','Newtown','Bars',array['After-work drinks','Date night','Birthday dinner']::text[],'A King Street pub with a garden bar, dining and live music upstairs at Waywards. Meet near Newtown station, then check the current gig programme and booking options.','324 King Street, Newtown NSW 2042',-33.8974674,151.179184,'https://bankhotel.com.au/','Sydney','{"src":"photos/bank-newtown.webp","smallSrc":"photos/bank-newtown-480.webp","width":960,"height":720,"alt":"The Bank Hotel exterior on King Street beside Newtown station.","title":"Bank Hotel, Newtown.jpg","author":"Sardaka (talk) 09:14, 26 December 2008 (UTC)","source":"https://commons.wikimedia.org/wiki/File:Bank_Hotel,_Newtown.jpg","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000044','The Imperial Erskineville','Erskineville','Bars',array['After-work drinks','Date night','Birthday dinner']::text[],'A lively local for rooftop drinks, drag performances and basement nights. Different spaces have different programmes and entry conditions; check the current event listings.','35 Erskineville Road, Erskineville NSW 2043',-33.8991723,151.1826169,'https://imperialerskineville.com.au/','Sydney','{"src":"photos/imperial-erskineville.webp","smallSrc":"photos/imperial-erskineville-480.webp","width":960,"height":720,"alt":"The Imperial Erskineville exterior, photographed in December 2021.","title":"Imperial Hotel December 2021.jpg","author":"Nick-D","source":"https://commons.wikimedia.org/wiki/File:Imperial_Hotel_December_2021.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000045','The Oaks Hotel','Neutral Bay','Bars',array['After-work drinks','Birthday dinner','Date night']::text[],'Gather beneath the big oak tree for pub food and an unhurried catch-up. The courtyard photograph shows the actual venue; check current dining and group-booking arrangements.','118 Military Road, Neutral Bay NSW 2089',-33.8299935,151.2194071,'https://oakshotel.com.au/','Sydney','{"src":"photos/oaks-neutral-bay.webp","smallSrc":"photos/oaks-neutral-bay-480.webp","width":960,"height":1280,"alt":"The courtyard beneath the oak tree at The Oaks Hotel in Neutral Bay.","title":"Courtyard under the oak tree at The Oaks Hotel, Neutral Bay, NSW 02.jpg","author":"Kgbo","source":"https://commons.wikimedia.org/wiki/File:Courtyard_under_the_oak_tree_at_The_Oaks_Hotel,_Neutral_Bay,_NSW_02.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000046','The Grounds of Alexandria','Alexandria','Cafes',array['Coffee dates','Family outings','Places to try']::text[],'Coffee, cafe meals and a garden setting in a former industrial precinct. The photograph shows floral decorations from 2019, not the current installation; check bookings and what is on before visiting.','7A/2 Huntley Street, Alexandria NSW 2015',-33.9106312,151.1942813,'https://thegrounds.com.au/dine-in/the-grounds-cafe/','Sydney','{"src":"photos/grounds-alexandria.webp","smallSrc":"photos/grounds-alexandria-480.webp","width":960,"height":1707,"alt":"Floral decorations at The Grounds of Alexandria, photographed in September 2019.","title":"Flowers at Grounds .jpg","author":"Watercolours1707","source":"https://commons.wikimedia.org/wiki/File:Flowers_at_Grounds_.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000047','Mamak — Haymarket','Haymarket','Food & drink',array['Birthday dinner','Family outings','Places to try']::text[],'Malaysian roti, satay and shared plates on Goulburn Street. This branch does not take reservations. The photograph is a dish served here in 2009, rather than a current menu image.','15 Goulburn Street, Haymarket NSW 2000',-33.8777175,151.2042284,'https://mamak.com.au/contact','Sydney','{"src":"photos/mamak.webp","smallSrc":"photos/mamak-480.webp","width":960,"height":642,"alt":"Chicken satay photographed at Mamak in Sydney in May 2009; not a current menu photograph.","title":"Chicken satay 86.jpg","author":"Alpha from Melbourne, Australia","source":"https://commons.wikimedia.org/wiki/File:Chicken_satay_86.jpg","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000048','Chat Thai — Thaitown','Haymarket','Food & drink',array['Birthday dinner','Date night','Places to try']::text[],'A Campbell Street stop for Thai dishes and a table of things to share. The photograph shows fish cakes served at this address in 2009; check current menus and group-booking requirements.','20 Campbell Street, Haymarket NSW 2000',-33.8791209,151.2063774,'https://chatthai.com.au/','Sydney','{"src":"photos/chat-thai.webp","smallSrc":"photos/chat-thai-480.webp","width":960,"height":642,"alt":"Thai fish cakes photographed at Chat Thai, 20 Campbell Street, Haymarket, in August 2009.","title":"Thawt Mun Pla Thai redfish cakes - Chat Thai, Haymarket.jpg","author":"Alpha from Melbourne, Australia","source":"https://commons.wikimedia.org/wiki/File:Thawt_Mun_Pla_Thai_redfish_cakes_-_Chat_Thai,_Haymarket.jpg","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000049','Barrenjoey Lighthouse walk','Palm Beach','Activities',array['Weekend wandering','Hidden gems','Places to try']::text[],'Walk uphill from Palm Beach for the sandstone lighthouse and Pittwater views. Steep sections and exposed weather call for sturdy shoes and water. Check track alerts; lighthouse interiors require a guided tour.','Barrenjoey Head, Palm Beach NSW 2108',-33.579995,151.329677,'https://www.nationalparks.nsw.gov.au/things-to-do/historic-buildings-places/barrenjoey-lighthouse','Sydney','{"src":"photos/barrenjoey.webp","smallSrc":"photos/barrenjoey-480.webp","width":960,"height":1280,"alt":"The sandstone Barrenjoey Lighthouse at Palm Beach.","title":"Barrenjoey Lighthouse.jpg","author":"FotoSleuth","source":"https://commons.wikimedia.org/wiki/File:Barrenjoey_Lighthouse.jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000050','Wylie''s Baths','Coogee','Activities',array['Weekend wandering','Places to try']::text[],'A historic tidal pool and sea-view kiosk south of Coogee Beach. November 2026: pool and downstairs access are closed for wall repairs; the upstairs kiosk remains open. Check the official conditions notice before planning a swim.','4B Neptune Street, Coogee NSW 2034',-33.9255844,151.2594111,'https://wylies.com.au/','Sydney','{"src":"photos/wylies-baths.webp","smallSrc":"photos/wylies-baths-480.webp","width":960,"height":720,"alt":"Wylie''s Baths tidal pool and coastal setting at Coogee; a historical photograph, not current pool conditions.","title":"Wylie''s Baths 04.jpg","author":"Collywolly","source":"https://commons.wikimedia.org/wiki/File:Wylie%27s_Baths_04.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000051','Auburn Botanic Gardens','Auburn','Outdoors',array['Family outings','Weekend wandering','Hidden gems']::text[],'Wander through garden paths, reflection pools and the Japanese garden. Check admission conditions and festival bookings; dogs are not permitted inside the gardens.','99 Chiswick Road, Auburn NSW 2144',-33.8593518,151.0173874,'https://www.cumberland.nsw.gov.au/auburn-botanic-gardens','Sydney','{"src":"photos/auburn-gardens.webp","smallSrc":"photos/auburn-gardens-480.webp","width":960,"height":720,"alt":"The reflection pool and gardens at Auburn Botanic Gardens.","title":"Auburn botanical garden reflection pool.jpg","author":"Sourav Biswas","source":"https://commons.wikimedia.org/wiki/File:Auburn_botanical_garden_reflection_pool.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000052','Bicentennial Park','Sydney Olympic Park','Activities',array['Family outings','Weekend wandering','Places to try']::text[],'Walk or cycle the shared paths, explore the mangrove boardwalks and make time for a lakeside picnic. Check current park access and parking registration requirements before setting out.','Australia Avenue, Sydney Olympic Park NSW 2127',-33.8441836,151.0781955,'https://www.sydneyolympicpark.nsw.gov.au/parks-and-playgrounds/bicentennial-park','Sydney','{"src":"photos/bicentennial-park.webp","smallSrc":"photos/bicentennial-park-480.webp","width":960,"height":640,"alt":"A tree-lined path at Bicentennial Park, Sydney Olympic Park.","title":"Bicentennial Park, Homebush Bay.JPG","author":"Kanags","source":"https://commons.wikimedia.org/wiki/File:Bicentennial_Park,_Homebush_Bay.JPG","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000053','Carriageworks','Eveleigh','Art & culture',array['Weekend wandering','Family outings','Places to try']::text[],'Exhibitions, performances and a farmers market in a former railway workshop. The photograph shows the market forecourt in 2018. Check the current programme, market dates and ticket requirements.','245 Wilson Street, Eveleigh NSW 2015',-33.8941553,151.1916021,'https://carriageworks.com.au/visit/','Sydney','{"src":"photos/carriageworks.webp","smallSrc":"photos/carriageworks-480.webp","width":960,"height":720,"alt":"The Carriageworks exterior and market forecourt in Eveleigh, photographed in August 2018.","title":"Carriageworks-farmers-market-sydney 05.jpg","author":"Jensbest","source":"https://commons.wikimedia.org/wiki/File:Carriageworks-farmers-market-sydney_05.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000054','Sydney Park','Alexandria','Outdoors',array['Family outings','Weekend wandering','Coffee dates']::text[],'Rolling hills, wetlands, playgrounds and a children''s cycling track. Choose a walking loop or a picnic spot, and check the council page for works, access and the rules for off-leash areas.','Sydney Park Road, Alexandria NSW 2015',-33.90983,151.18517,'https://www.cityofsydney.nsw.gov.au/parks/sydney-park','Sydney','{"src":"photos/sydney-park.webp","smallSrc":"photos/sydney-park-480.webp","width":960,"height":640,"alt":"A wetland and walking paths in Sydney Park, photographed in April 2026.","title":"Wetland area in Sydney Park April 2026.jpg","author":"Nick-D","source":"https://commons.wikimedia.org/wiki/File:Wetland_area_in_Sydney_Park_April_2026.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
